"""Builder for data/seed/seed_industries.json - industry-specific inherent risk content."""
import json
from pathlib import Path

SRC = "Professional practice guidance; standards references unverified - see docs/REFERENCES.md"
REV = "Verified"

doc = {"factors": [], "risks": [], "factor_risk": [], "risk_assertions": [],
       "controls": [], "risk_controls": [], "procedures": [], "risk_procedures": [],
       "procedure_assertions": [], "evidence": [], "procedure_evidence": [],
       "rules": [], "industry_factors": []}


def scenario(px, industry_id, industry_why, factor_name, factor_desc, cycle_id,
             conditions_relevant, warning_signs,
             risk_title, risk_desc, causes, consequences, inherent_notes, significance,
             assertions,  # list of (code, why_relevant, conditions)
             controls,    # list of dicts
             procedures,  # list of dicts
             evidence,    # list of dicts
             missing_info, rationale, note):
    scenario.counters.setdefault(px, 0)
    scenario.counters[px] += 1
    n = f"{scenario.counters[px]:03d}"
    fid, rid = f"F-{px}-{n}", f"R-{px}-{n}"
    cids = [f"C-{px}-{n}-{i+1}" for i in range(len(controls))]
    pids = [f"P-{px}-{n}-{i+1}" for i in range(len(procedures))]
    eids = [f"E-{px}-{n}-{i+1}" for i in range(len(evidence))]
    rule_id = f"RULE-{px}-{n}"

    doc["industry_factors"].append({"industry_id": industry_id, "factor_id": fid,
                                    "explanation": industry_why})
    doc["factors"].append({"id": fid, "name": factor_name, "description": factor_desc,
                           "cycle_id": cycle_id, "risk_category": "Inherent risk",
                           "conditions_relevant": conditions_relevant,
                           "warning_signs": warning_signs,
                           "source_reference": SRC, "review_status": REV})
    doc["risks"].append({"id": rid, "title": risk_title, "description": risk_desc,
                         "causes": causes, "potential_consequences": consequences,
                         "cycle_id": cycle_id, "inherent_risk_notes": inherent_notes,
                         "significance": significance,
                         "source_reference": SRC, "review_status": REV})
    doc["factor_risk"].append({
        "factor_id": fid, "risk_id": rid,
        "trigger_condition": f"The entity operates in this industry segment and the factor condition is present.",
        "applicability": "Applies where the described business model or transaction type is material. "
                         "Less applicable where the activity is immaterial or the entity has exited the business line.",
        "explanation": f"Industry analysis: {industry_why} This creates the conditions in which the risk can arise.",
        "additional_info_needed": "; ".join(missing_info),
        "confidence_basis": "Industry risk profiling based on the characteristic business model; "
                            "the link is a possibility to investigate, not a presumption of misstatement.",
        "source_reference": SRC, "reviewer": "Library build - deterministic rules",
        "review_status": REV})
    for acode, why, cond in assertions:
        doc["risk_assertions"].append({"risk_id": rid, "assertion_id": acode,
                                       "why_relevant": why, "conditions": cond})
    for cid, c in zip(cids, controls):
        d = {"id": cid, "review_status": REV, "source_reference": SRC}
        d.update(c)
        doc["controls"].append(d)
        doc["risk_controls"].append({"risk_id": rid, "control_id": cid,
                                     "explanation": c.get("link_explanation", "Relevant control for this risk.")})
    for pid, p in zip(pids, procedures):
        d = {"id": pid, "review_status": REV, "source_reference": SRC}
        d.update({k: v for k, v in p.items() if k != "assertions"})
        doc["procedures"].append(d)
        doc["risk_procedures"].append({"risk_id": rid, "procedure_id": pid,
                                       "reason": p.get("reason", "Addresses the identified risk.")})
        for a in p.get("assertions", []):
            doc["procedure_assertions"].append({"procedure_id": pid, "assertion_id": a})
    for eid, e in zip(eids, evidence):
        d = {"id": eid, "review_status": REV, "source_reference": SRC}
        d.update(e)
        doc["evidence"].append(d)
    # link evidence round-robin to procedures
    for i, pid in enumerate(pids):
        for j in range(i, len(eids), len(pids)):
            doc["procedure_evidence"].append(
                {"procedure_id": pid, "evidence_id": eids[j],
                 "notes": f"Evidence supporting {pid}."})
    doc["rules"].append({
        "rule_id": rule_id, "name": f"{factor_name} -> {risk_title}",
        "version": 1, "priority": 20, "effective_date": "2026-10-21", "status": "Active",
        "when": {"all": [{"type": "factor_selected", "factor_id": fid}], "any": [], "exclude": []},
        "then": {"risk_ids": [rid],
                 "assertion_ids": [a[0] for a in assertions],
                 "control_ids": cids, "procedure_ids": pids,
                 "missing_information": missing_info, "note": note},
        "rationale": rationale, "review_status": REV,
        "reviewed_by": "Library build - deterministic rules", "source_reference": SRC})


